import{_ as a,o as e,c as o,a3 as d}from"./chunks/framework.D1iekJsc.js";const u=JSON.parse('{"title":"在 MiniTavern 中配置","description":"MiniTavern 連接 Ollama、LM Studio、KoboldCPP、llama.cpp：設置 → 模型連接，填寫 OpenAI 兼容 Base URL 與測連。","frontmatter":{"title":"在 MiniTavern 中配置","description":"MiniTavern 連接 Ollama、LM Studio、KoboldCPP、llama.cpp：設置 → 模型連接，填寫 OpenAI 兼容 Base URL 與測連。","head":[["meta",{"name":"keywords","content":"酒館,AI酒館,Ai酒館,迷你酒館,超迷你酒館,MiniTavern,AI夥伴,AI朋友,Ai本地聊天,Silly Tavern,SillyTavern,手機玩Silly Tavern,Silly Tavern手機版,Silly Tavern安卓,Silly Tavern蘋果,AI角色扮演,角色卡,角色扮演,AI聊天,手機AI,離線AI,AI劇情,本地大模型,本地模型,Ollama,LM Studio,世界書,正則,BYOK,使用手冊,教學,character card,AI roleplay,AI companion"}],["meta",{"property":"og:title","content":"在 MiniTavern 中配置 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern 連接 Ollama、LM Studio、KoboldCPP、llama.cpp：設置 → 模型連接，填寫 OpenAI 兼容 Base URL 與測連。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/zh-TW/connect-app/minitavern"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/zh-TW/connect-app/minitavern"}]]},"headers":[],"relativePath":"zh-TW/connect-app/minitavern.md","filePath":"zh-TW/connect-app/minitavern.md","lastUpdated":1787224147000}'),r={name:"zh-TW/connect-app/minitavern.md"};function l(i,t,n,c,s,h){return e(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="在-minitavern-中配置" tabindex="-1">在 MiniTavern 中配置 <a class="header-anchor" href="#在-minitavern-中配置" aria-label="Permalink to &quot;在 MiniTavern 中配置&quot;">​</a></h1><p>本文對應 App 內路徑：<strong>設置 → 模型 → 模型連接</strong>。</p><h2 id="新建連接" tabindex="-1">新建連接 <a class="header-anchor" href="#新建連接" aria-label="Permalink to &quot;新建連接&quot;">​</a></h2><ol><li>打開 MiniTavern → 底部 <strong>設置</strong>。</li><li>進入 <strong>模型</strong> → <strong>模型連接</strong>。</li><li>點右上角 <strong>新建</strong>。</li><li><strong>模型平臺</strong> 選擇 <strong>自定義</strong>（OpenAI 兼容 / 自定義 Base URL，以當前版本選項文案為準）。</li><li>按你的工具填寫下表，保存；若支持 <strong>測連</strong>，先測連再設為默認。</li></ol><h2 id="各工具示例" tabindex="-1">各工具示例 <a class="header-anchor" href="#各工具示例" aria-label="Permalink to &quot;各工具示例&quot;">​</a></h2><p>將 <code>YOUR_PC_IP</code> 換成電腦局域網 IP（不要用 <code>localhost</code>）。</p><table tabindex="0"><thead><tr><th>工具</th><th>Base URL 示例</th><th>模型名</th><th>API Key</th></tr></thead><tbody><tr><td><a href="/ultra_guides/zh-TW/ollama/lan">Ollama</a></td><td><code>http://YOUR_PC_IP:11434/v1</code></td><td><code>ollama list</code> 中的名稱</td><td>可空或 <code>ollama</code></td></tr><tr><td><a href="/ultra_guides/zh-TW/lmstudio/server">LM Studio</a></td><td><code>http://YOUR_PC_IP:1234/v1</code></td><td>Local Server 中的 id</td><td>可空</td></tr><tr><td><a href="/ultra_guides/zh-TW/koboldcpp/server">KoboldCPP</a></td><td><code>http://YOUR_PC_IP:5001/v1</code></td><td><code>/v1/models</code> 中的 id</td><td>可空</td></tr><tr><td><a href="/ultra_guides/zh-TW/llamacpp/server">llama.cpp</a></td><td><code>http://YOUR_PC_IP:8080/v1</code></td><td>server 返回的 id</td><td>可空</td></tr><tr><td><a href="/ultra_guides/zh-TW/localai/install">LocalAI</a></td><td><code>http://YOUR_PC_IP:8080/v1</code></td><td>LocalAI 配置名</td><td>按是否鑑權</td></tr><tr><td><a href="/ultra_guides/zh-TW/jan/install">Jan</a></td><td>應用 API 頁顯示的地址</td><td>列表中的 id</td><td>按應用設置</td></tr><tr><td><a href="/ultra_guides/zh-TW/textgen/install">text-generation-webui</a></td><td><code>http://YOUR_PC_IP:端口/v1</code></td><td>擴展返回的 id</td><td>按擴展設置</td></tr></tbody></table><p>別名可自定，例如 <code>家裡Ollama</code>、<code>書房Kobold</code>。</p><h2 id="設為默認並開聊" tabindex="-1">設為默認並開聊 <a class="header-anchor" href="#設為默認並開聊" aria-label="Permalink to &quot;設為默認並開聊&quot;">​</a></h2><ol><li>在模型連接列表中設為 <strong>默認</strong>。</li><li>導入或選擇角色卡，進入聊天發一條消息。</li><li>電腦端對應工具應出現請求活動；App 內應收到流式或完整回覆。</li></ol><h2 id="會話級覆蓋-可選" tabindex="-1">會話級覆蓋（可選） <a class="header-anchor" href="#會話級覆蓋-可選" aria-label="Permalink to &quot;會話級覆蓋（可選）&quot;">​</a></h2><p>某個聊天要臨時換本地模型：在聊天設置裡覆蓋全局默認模型連接 / 參數。</p><h2 id="注意" tabindex="-1">注意 <a class="header-anchor" href="#注意" aria-label="Permalink to &quot;注意&quot;">​</a></h2><ul><li><strong>禁止</strong> 在手機上填 <code>http://localhost:...</code> 或 <code>http://127.0.0.1:...</code>。</li><li>URL 末尾建議帶 <code>/v1</code>，不要填到 <code>/chat/completions</code>。</li><li>電腦休眠、合蓋、切網絡後 IP 可能變化。</li><li>端口以你實際開啟的為準，上表僅為常見默認。</li></ul><p>連不上請看 <a href="/ultra_guides/zh-TW/troubleshoot">排錯對照表</a>。選工具見 <a href="/ultra_guides/zh-TW/local/tools">工具總覽</a>。</p>',15)])])}const m=a(r,[["render",l]]);export{u as __pageData,m as default};
